import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"结果与历史","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/results.md","filePath":"zh/guide/results.md","lastUpdated":1792570296000}'),d={name:"zh/guide/results.md"};function s(h,a,n,i,l,p){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="结果与历史" tabindex="-1">结果与历史 <a class="header-anchor" href="#结果与历史" aria-label="Permalink to &quot;结果与历史&quot;">​</a></h1><p>阅读检索清单，选择重要文献，再导入自己的研究流程。</p><h2 id="三类独立历史" tabindex="-1">三类独立历史 <a class="header-anchor" href="#三类独立历史" aria-label="Permalink to &quot;三类独立历史&quot;">​</a></h2><p>检索运行、分析和综述分别保存，侧栏中的每个模块只显示自己的历史。历史保存在哪里、记录如何重命名、导出或删除，以及刷新后什么会保留，见<a href="./workspace">工作区与历史</a>。</p><h2 id="阅读文献卡片" tabindex="-1">阅读文献卡片 <a class="header-anchor" href="#阅读文献卡片" aria-label="Permalink to &quot;阅读文献卡片&quot;">​</a></h2><p>结果可能包含标题、作者、年份、发表载体、摘要、原始链接、标识符、引用信息和相关性理由，具体取决于数据源。</p><p>相关性衡量与<strong>你的问题</strong>的匹配程度，不是研究质量评分，也不能代替阅读原文。</p><h2 id="筛选、排序和选择" tabindex="-1">筛选、排序和选择 <a class="header-anchor" href="#筛选、排序和选择" aria-label="Permalink to &quot;筛选、排序和选择&quot;">​</a></h2><p>结果控件针对本次返回的集合进行搜索、筛选与排序，不会重新向外部数据源检索。</p><p>勾选文献可导出子集或整理综述，继续前应确认已选数量。<strong>选择已加载</strong>只勾选当前已加载的文献，创建综述需选择 2–256 篇。切换模块会保留本次会话中的勾选。</p><h2 id="导出" tabindex="-1">导出 <a class="header-anchor" href="#导出" aria-label="Permalink to &quot;导出&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格式</th><th>用途</th></tr></thead><tbody><tr><td>CSV</td><td>表格整理与人工筛选</td></tr><tr><td>JSON</td><td>后续程序处理</td></tr><tr><td>已选 CSV / JSON</td><td>仅包含勾选文献</td></tr></tbody></table><p><strong>导出</strong>菜单集中提供全部结果和已选文献的 CSV / JSON 下载。完整导出覆盖已保存结果，不仅是当前分页。原始记录链接指向数据源，PaperSeek 不会批量下载付费全文。</p><p><a href="./reviews">综述导出</a>使用 Markdown、Word 与 BibTeX。</p><h2 id="重新打开历史" tabindex="-1">重新打开历史 <a class="header-anchor" href="#重新打开历史" aria-label="Permalink to &quot;重新打开历史&quot;">​</a></h2><p>社区版历史属于本地数据库，在线历史属于已登录账户。<a href="./../online/privacy#不登录检索">匿名检索后再登录</a>不会自动补存。</p><p>历史保留当时的实际设置，不会被今天的默认模型或预算覆盖；旧版未记录的字段保持未知。</p><p>可删除已结束的记录，删除前请导出需要保留的内容，活动任务必须先结束。</p><h2 id="创建综述" tabindex="-1">创建综述 <a class="header-anchor" href="#创建综述" aria-label="Permalink to &quot;创建综述&quot;">​</a></h2><p>选择至少两篇具有有效摘要的文献，或从 <strong>文献综述</strong> 新建。后续步骤见<a href="./reviews">大纲与写作指南</a>。</p>',20)])])}const _=t(d,[["render",s]]);export{u as __pageData,_ as default};
